 p=next(B.glob(n+'-*.md')); a=Path('wiki/reviews/correzioni-collana-2026-10-02/archive/pre-correzioni-sp04-'+n+'.md');assert not a.exists();shutil.copyfile(p,a);return p,p.read_text(encoding='utf8')
